-- Normalize one non-negative decimal digit string without changing its exact value.
-- 规范化一个非负十进制数字字符串，且不改变其精确值。
--
-- value is a digit-only string.
-- value 是一个只包含数字的字符串。
-- Returns a canonical digit string with at least one digit.
-- 返回至少包含一位数字的规范数字字符串。
local function normalize_unsigned_integer(value)
    if type(value) ~= "string" or value:match("^%d+$") == nil then
        error("Vulcan Usage Statistics requires an unsigned integer string")
    end
    local normalized = value:gsub("^0+", "")
    if normalized == "" then
        return "0"
    end
    return normalized
end

-- Add two arbitrary-precision non-negative integer strings.
-- 对两个任意精度非负整数字符串求和。
--
-- left and right are normalized or zero-padded digit strings.
-- left 与 right 是规范化或补零后的数字字符串。
-- Returns their exact integer sum as a canonical digit string.
-- 返回规范数字字符串形式的精确整数和。
local function add_unsigned_integers(left, right)
    left = normalize_unsigned_integer(left)
    right = normalize_unsigned_integer(right)
    local left_index = #left
    local right_index = #right
    local carry = 0
    local reversed = {}
    while left_index > 0 or right_index > 0 or carry > 0 do
        local left_digit = 0
        if left_index > 0 then
            left_digit = string.byte(left, left_index) - 48
            left_index = left_index - 1
        end
        local right_digit = 0
        if right_index > 0 then
            right_digit = string.byte(right, right_index) - 48
            right_index = right_index - 1
        end
        local total = left_digit + right_digit + carry
        reversed[#reversed + 1] = tostring(total % 10)
        carry = math.floor(total / 10)
    end
    local digits = {}
    for index = #reversed, 1, -1 do
        digits[#digits + 1] = reversed[index]
    end
    return table.concat(digits)
end

-- Multiply two arbitrary-precision non-negative integer strings.
-- 对两个任意精度非负整数字符串求积。
--
-- left and right are digit-only strings.
-- left 与 right 是只包含数字的字符串。
-- Returns their exact integer product as a canonical digit string.
-- 返回规范数字字符串形式的精确整数积。
local function multiply_unsigned_integers(left, right)
    left = normalize_unsigned_integer(left)
    right = normalize_unsigned_integer(right)
    if left == "0" or right == "0" then
        return "0"
    end
    local digits = {}
    for index = 1, #left + #right do
        digits[index] = 0
    end
    for left_index = #left, 1, -1 do
        local left_digit = string.byte(left, left_index) - 48
        for right_index = #right, 1, -1 do
            local right_digit = string.byte(right, right_index) - 48
            local position = left_index + right_index
            digits[position] = digits[position] + left_digit * right_digit
        end
    end
    for position = #digits, 2, -1 do
        local carry = math.floor(digits[position] / 10)
        digits[position] = digits[position] % 10
        digits[position - 1] = digits[position - 1] + carry
    end
    local output = {}
    local started = false
    for _, digit in ipairs(digits) do
        if digit ~= 0 or started then
            started = true
            output[#output + 1] = tostring(digit)
        end
    end
    return table.concat(output)
end

-- Parse one non-negative catalog price into integer digits and a decimal scale.
-- 将一个非负目录价格解析为整数数字与十进制小数位数。
--
-- value is one exact decimal string from the plugin-owned catalog.
-- value 是插件自有价目表中的一个精确十进制字符串。
-- Returns canonical digits followed by the fractional scale.
-- 返回规范数字以及小数位数。
local function parse_catalog_decimal(value)
    if type(value) ~= "string" then
        error("Vulcan Usage Statistics catalog price must be a string")
    end
    local whole, fraction = value:match("^(%d+)%.(%d+)$")
    if whole == nil then
        whole = value:match("^(%d+)$")
        fraction = ""
    end
    if whole == nil then
        error("Vulcan Usage Statistics catalog price is not a non-negative decimal: " .. value)
    end
    return normalize_unsigned_integer(whole .. fraction), #fraction
end

-- Convert one SQLite JSON integer Token count into exact decimal digits.
-- 将一个 SQLite JSON 整数 Token 数转换为精确十进制数字。
--
-- value is one nullable Token fact.
-- value 是一个可为空的 Token 事实。
-- Returns nil for unknown data or exact digits for a non-negative integer.
-- 对未知数据返回 nil，对非负整数返回精确数字。
local function token_digits(value)
    if value == nil or value == vulcan.json.null then
        return nil
    end
    if type(value) ~= "number" or value % 1 ~= 0 or value < 0 or value > 9007199254740991 then
        error("Vulcan Usage Statistics requires non-negative integer Token facts")
    end
    return string.format("%.0f", value)
end

-- Render exact scaled integer digits as a canonical decimal string.
-- 将精确的缩放整数数字渲染为规范十进制字符串。
--
-- digits is an unsigned integer and scale is its fractional digit count.
-- digits 是无符号整数，scale 是其小数位数。
-- Returns an exact decimal string without insignificant trailing zeros.
-- 返回不含无意义尾零的精确十进制字符串。
local function format_scaled_decimal(digits, scale)
    digits = normalize_unsigned_integer(digits)
    if scale == 0 then
        return digits
    end
    if #digits <= scale then
        digits = string.rep("0", scale - #digits + 1) .. digits
    end
    local split = #digits - scale
    local whole = digits:sub(1, split)
    local fraction = digits:sub(split + 1):gsub("0+$", "")
    if fraction == "" then
        return whole
    end
    return whole .. "." .. fraction
end

-- PRICE_DIMENSIONS joins the shared price keys and the matching recorded Token fields.
-- PRICE_DIMENSIONS 对应共享价格键和实际记录的 Token 字段。
local PRICE_DIMENSIONS = {
    { usd = "inputPerMillion", cny = "inputPerMillionCny", tokens = "uncachedInputTokens" },
    { usd = "outputPerMillion", cny = "outputPerMillionCny", tokens = "outputTokens" },
    { usd = "cacheReadPerMillion", cny = "cacheReadPerMillionCny", tokens = "cacheReadTokens" },
    { usd = "cacheWritePerMillion", cny = "cacheWritePerMillionCny", tokens = "cacheWriteTokens" },
}

-- Return the normalized key and whether its Preview marker was removed.
-- 返回规范化键，以及是否移除了其 Preview 标记。
local function billing_model_format(key)
    -- Claude uses hyphenated minor versions and encodes thinking as a request setting.
    -- Claude 的小版本使用连字符，思考模式由请求设置表达。
    local claude = key:sub(1, 7) == "claude-"
    local stem = claude and key:gsub("%-thinking$", "") or key
    stem = stem:match("^(.+)[-@]20%d%d%d%d%d%d$") or stem:match("^(.+)%-20%d%d%-%d%d%-%d%d$") or stem
    local preview = stem:match("^(.+)%-preview%-latest$") or stem:match("^(.+)%-preview$")
    local normalized = preview or stem
    if claude then normalized = normalized:gsub("%.", "-") end
    return normalized, preview ~= nil
end

-- Return the most specific known stem in key and its length.
-- 返回 key 中最具体的已知型号段及其长度。
local function billing_segment_match(key)
    -- Start at the complete key, then walk backward over hyphens with a nonempty suffix.
    -- 从完整键开始，只沿后方有非空后缀的连字符向前查找。
    local stem = key
    local boundary = key:sub(1, -2):match("^.*()%-")
    while #stem > 0 do
        local canonical = DECLARED_MODEL_PREFIXES[stem] or DECLARED_MODEL_ALIASES[stem]
        if canonical ~= nil and (DECLARED_MODEL_PREFIXES[stem] ~= nil or canonical:lower() == stem) then
            return canonical, #stem
        end
        if boundary == nil then break end
        stem = key:sub(1, boundary - 1)
        boundary = stem:match("^.*()%-")
    end
    return nil, 0
end

-- Return the shared billing ID for model_id, preserving exact prices before format rules.
-- 返回 model_id 的共享计费标识，先匹配精确报价，再应用写法规则。
local function billing_model_id(model_id)
    -- suffix keeps version and variant markers as part of the billing identity.
    -- suffix 将版本与变体标记保留为定价标识的一部分。
    local suffix = model_id:match("[^/]+$") or model_id
    -- key is the case-folded suffix used by both lookup tables.
    -- key 是两张查找表共用的大小写折叠后缀。
    local key = suffix:lower()
    if DECLARED_MODEL_ALIASES[key] ~= nil then return DECLARED_MODEL_ALIASES[key] end
    -- Date and Claude fallback need a known model, while Preview always owns the base row.
    -- 日期和 Claude 的回退需要已知主型号，Preview 则统一使用去后缀的费用行。
    local normalized, is_preview = billing_model_format(key)
    if DECLARED_MODEL_ALIASES[normalized] ~= nil then return DECLARED_MODEL_ALIASES[normalized] end
    -- Compare stem lengths across the original and normalized spellings, preferring the original on ties.
    -- 比较原始和规范写法命中的型号段长度，同长度时优先使用原始写法。
    local canonical, length = billing_segment_match(key)
    if normalized ~= key then
        local formatted, formatted_length = billing_segment_match(normalized)
        if formatted_length > length then canonical = formatted end
    end
    return canonical or (is_preview and normalized or suffix)
end

-- Resolve a provider's exact catalog models before applying shared aliases.
-- 先解析供应商有独立报价的精确型号，再应用共享别名。
-- Returns the provider's billing ID for model_id, or its shared billing ID.
-- 返回 model_id 的供应商计费标识；没有独立型号时返回共享计费标识。
local function provider_billing_model_id(model_id, provider_id)
    local refs = DEFAULT_PRICING_CATALOG.provider_models[provider_id]
    local suffix = (model_id:match("[^/]+$") or model_id):lower()
    if refs ~= nil and refs[suffix] ~= nil then return suffix end
    return billing_model_id(model_id)
end

-- Return a SQL expression for the last slash component of a trusted model ID column.
-- 为可信的模型标识列返回提取最后一个斜杠分段的 SQL 表达式。
local function model_id_suffix_sql(column)
    -- Trim the characters that can occur after the last slash, leaving the prefix intact.
    -- 去掉最后一个斜杠之后的字符，保留前缀用于定位后缀。
    return "COALESCE(NULLIF(substr(" .. column .. ", length(rtrim(" .. column ..
        ", replace(" .. column .. ", '/', ''))) + 1), ''), " .. column .. ")"
end

-- Return the SQL form of the billing identity for a trusted column in a query with billing_aliases.
-- 为包含 billing_aliases 的查询中的可信列名返回定价标识 SQL 表达式。
local function billing_model_sql(column)
    -- suffix and key are the raw and case-folded forms of the final slash component.
    -- suffix 和 key 分别是最后一个斜杠分段的原始写法和大小写折叠写法。
    local suffix = model_id_suffix_sql(column)
    local key = "lower(" .. suffix .. ")"
    -- Keep the fallback in a scalar query so exact prices never require normalization.
    -- 将回退放在标量查询内，精确报价命中时无需执行归一化。
    return "COALESCE((SELECT model_id FROM billing_aliases WHERE model_suffix = " .. key ..
        "), (WITH spelling(key) AS (SELECT " .. key .. [[),
    mode_stem AS (
        SELECT key, CASE WHEN key GLOB 'claude-*' AND substr(key, -9) = '-thinking'
            THEN substr(key, 1, length(key) - 9) ELSE key END AS stem
        FROM spelling
    ), date_stem AS (
        SELECT key, CASE
            WHEN length(stem) > 9 AND substr(stem, -9) GLOB '[-@]20[0-9][0-9][0-9][0-9][0-9][0-9]'
                THEN substr(stem, 1, length(stem) - 9)
            WHEN length(stem) > 11 AND substr(stem, -11) GLOB '-20[0-9][0-9]-[0-9][0-9]-[0-9][0-9]'
                THEN substr(stem, 1, length(stem) - 11)
            ELSE stem END AS stem
        FROM mode_stem
    ), preview_stem AS (
        SELECT key, stem, CASE
            WHEN length(stem) > 15 AND substr(stem, -15) = '-preview-latest' THEN substr(stem, 1, length(stem) - 15)
            WHEN length(stem) > 8 AND substr(stem, -8) = '-preview' THEN substr(stem, 1, length(stem) - 8)
            ELSE stem END AS base
        FROM date_stem
    ), formatted AS (
        SELECT key, base <> stem AS is_preview, CASE WHEN key GLOB 'claude-*' THEN replace(base, '.', '-') ELSE base END AS normalized
        FROM preview_stem
    ), segment_candidates AS (
        SELECT key AS spelling, 0 AS priority FROM formatted
        UNION ALL
        SELECT normalized AS spelling, 1 AS priority FROM formatted WHERE normalized <> key
    )
    SELECT COALESCE((SELECT model_id FROM billing_aliases WHERE model_suffix = formatted.normalized),
        (SELECT p.model_id FROM segment_candidates c JOIN billing_prefixes p
            ON c.spelling = p.prefix OR (length(c.spelling) > length(p.prefix) + 1
                AND substr(c.spelling, 1, length(p.prefix) + 1) = p.prefix || '-')
            ORDER BY length(p.prefix) DESC, c.priority, p.prefix LIMIT 1),
        CASE WHEN is_preview THEN normalized END)
    FROM formatted), ]] .. suffix .. ")"
end

-- Encode the exact and family mappings for the bound SQL lookup parameter.
-- 将精确映射和系列映射编码为绑定的 SQL 查找参数。
local function billing_lookup_json()
    return vulcan.json.encode({ exact = DECLARED_MODEL_ALIASES, prefixes = DECLARED_MODEL_PREFIXES })
end

-- Return lookup CTE definitions for a trusted JSON parameter placeholder.
-- 根据可信的 JSON 参数占位符返回查找用 CTE 定义。
local function billing_lookup_sql(parameter)
    return "billing_aliases AS MATERIALIZED (SELECT key AS model_suffix, value AS model_id FROM json_each(" ..
        parameter .. ", '$.exact')), billing_prefixes AS MATERIALIZED (SELECT key AS prefix, value AS model_id FROM json_each(" ..
        parameter .. ", '$.prefixes') UNION SELECT model_suffix, model_id FROM billing_aliases WHERE model_suffix = lower(model_id))"
end

-- Build a stable signature of configured amounts and tariff settings for legacy conflict detection.
-- 生成配置金额和时段设置的稳定签名，用于检测历史别名价格冲突。
-- context_tiers carries the nested off-peak tiers when supplied separately from prices.
-- context_tiers 在谷价档位与单价分开存放时传入该档位。
local function price_signature(prices, context_tiers)
    -- values preserve explicit currency choices, including zero and absent values.
    -- values 保留显式币种选择，包括零值和缺省值。
    local values = {}
    for _, dimension in ipairs(PRICE_DIMENSIONS) do
        values[#values + 1] = prices[dimension.usd] or ""
        values[#values + 1] = prices[dimension.cny] or ""
    end
    for _, tier in ipairs(context_tiers or prices.contextTiers or EMPTY_ARRAY) do
        values[#values + 1] = ">" .. token_digits(tier.aboveInputTokens) .. ":" .. price_signature(tier.prices)
    end
    if prices.offPeak ~= nil then
        values[#values + 1] = price_signature(prices.offPeak.prices, prices.offPeak.contextTiers)
        values[#values + 1] = tostring(prices.offPeak.utcOffsetMinutes)
        for _, window in ipairs(prices.offPeak.windows) do
            values[#values + 1] = table.concat({ window.days, window.start, window["end"] }, "/")
        end
    end
    return table.concat(values, ":")
end

-- Group explicit overrides by billing ID without modifying persisted legacy keys.
-- 按定价标识聚合显式覆盖价，保留已持久化的历史键。
local function index_model_overrides(model_overrides, provider_id)
    -- groups separates shared prices from legacy keys with competing prices.
    -- groups 区分可共享单价与价格冲突的历史键。
    local groups = {}
    for model_id, prices in pairs(model_overrides) do
        -- Compare the exact settings within the resolved billing group.
        -- 在解析后的定价组内比较精确设置。
        local canonical = provider_billing_model_id(model_id, provider_id)
        local signature = price_signature(prices)
        local group = groups[canonical]
        if group == nil then
            groups[canonical] = { prices = prices, signature = signature, conflict = false }
        elseif group.signature ~= signature then
            -- Until the user resolves a conflict, each old exact key retains its own price.
            -- 用户解决冲突前，各历史精确键仍保留自己的价格。
            group.conflict = true
        end
    end
    return groups
end

-- Index shared and provider-bound model overrides independently for one settings snapshot.
-- 为一份设置快照分别索引共享和绑定供应商的模型覆盖。
local function index_pricing_overrides(config)
    -- Each provider owns a separate model namespace even when it uses the same aliases.
    -- 即使使用相同的别名，每家供应商也有独立的模型命名空间。
    local providers = {}
    for provider_id, prices in pairs(config.providerOverrides or {}) do
        providers[provider_id] = { prices = prices, groups = index_model_overrides(prices, provider_id), provider_id = provider_id }
    end
    return {
        shared = { prices = config.modelOverrides, groups = index_model_overrides(config.modelOverrides) },
        providers = providers,
    }
end

-- Define weekly billing boundaries on a Monday-based minute grid in UTC.
-- 在以周一为首日的 UTC 分钟网格上定义每周计费边界。
local DAY_MINUTES = 24 * 60
local WEEK_MINUTES = 7 * DAY_MINUTES
local UNIX_EPOCH_WEEK_MINUTE = 3 * DAY_MINUTES
local MILLISECONDS_PER_MINUTE = 60 * 1000

-- Convert a validated HH:MM value into minutes from midnight.
-- 将已校验的 HH:MM 值转换为从午夜起算的分钟。
local function clock_minutes(clock)
    return tonumber(clock:sub(1, 2)) * 60 + tonumber(clock:sub(4, 5))
end

-- Compile an off-peak rule into half-open UTC week intervals, splitting at the week boundary.
-- 将谷价规则编译为 UTC 周内的左闭右开区间，跨周时拆分。
-- Returns nil for models without a schedule and rejects zero-length windows.
-- 模型无时段配置时返回 nil，并拒绝长度为零的时段。
local function weekly_windows(off_peak)
    if off_peak == nil then return nil end
    -- intervals is the shared weekly representation for both Lua and SQL matching.
    -- intervals 是 Lua 与 SQL 匹配共用的周内表示。
    local intervals = vulcan.json.array()
    for _, window in ipairs(off_peak.windows) do
        -- A cross-midnight window belongs to its start day and extends into the next day.
        -- 跨午夜时段归属于开始日，并延续到次日。
        local start, finish = clock_minutes(window.start), clock_minutes(window["end"])
        if start == finish then error("Off-peak windows must have different start and end times") end
        if finish < start then finish = finish + DAY_MINUTES end
        local first = window.days == "weekend" and 5 or 0
        local last = window.days == "weekdays" and 4 or 6
        for day = first, last do
            -- Offset the local bounds into UTC and split intervals that cross UTC Monday.
            -- 将本地边界换算为 UTC，并拆分跨越 UTC 周一的区间。
            local lower = (day * DAY_MINUTES + start - off_peak.utcOffsetMinutes) % WEEK_MINUTES
            local upper = lower + finish - start
            intervals[#intervals + 1] = { lower = lower, upper = math.min(upper, WEEK_MINUTES) }
            if upper > WEEK_MINUTES then
                intervals[#intervals + 1] = { lower = 0, upper = upper - WEEK_MINUTES }
            end
        end
    end
    return intervals
end

-- Compile ascending thresholds for the selected price table, or nil for a flat rate.
-- 编译所选费率表的升序阈值，单一费率返回 nil。
-- prices owns optional context tiers. Equal or descending thresholds are rejected.
-- prices 持有可选的上下文档位。相同或降序的阈值会被拒绝。
local function context_thresholds(prices)
    if prices.contextTiers == nil then return nil end
    -- Thresholds retain integer comparisons in SQL and identify their corresponding rate.
    -- 阈值在 SQL 中按整数比较，同时标识对应费率。
    local thresholds = vulcan.json.array()
    for _, tier in ipairs(prices.contextTiers) do
        if #thresholds > 0 and tier.aboveInputTokens <= thresholds[#thresholds] then
            error("Context pricing thresholds must be strictly increasing")
        end
        thresholds[#thresholds + 1] = tier.aboveInputTokens
    end
    return thresholds
end

-- Project the rate selection rules for one price entry, returning nil for a flat rate.
-- 投影一项价格的费率选择规则，单一费率返回 nil。
-- prices includes base prices and may include off-peak rates and context tiers.
-- prices 包含基础单价，也可包含谷价与上下文档位。
local function tariff_rule(prices)
    -- Select the time-based price table before selecting an input-length tier.
    -- 先选择时段对应的费率表，再根据输入长度选择档位。
    local rule = vulcan.json.object()
    rule.baseThresholds = context_thresholds(prices)
    if prices.offPeak ~= nil then
        rule.windows = weekly_windows(prices.offPeak)
        rule.offPeakThresholds = context_thresholds(prices.offPeak)
    end
    if next(rule) ~= nil then return rule end
end

-- Add one scope's overrides; a flat rule shadows any lower priority schedule.
-- 添加一个范围的覆盖价；单一费率屏蔽更低优先级的时段费率。
local function add_override_rules(rules, scope)
    for model_id, group in pairs(scope.groups) do
        if not group.conflict then
            -- A provider's flat tariff still takes precedence over shared windows and tiers.
            -- 供应商的单一费率仍优先于共享的时段及档位。
            rules.shared[model_id] = tariff_rule(group.prices) or vulcan.json.object()
        end
    end
    for model_id, prices in pairs(scope.prices) do
        if scope.groups[provider_billing_model_id(model_id, scope.provider_id)].conflict then
            -- An empty object shadows a shared rule for this exact legacy key.
            -- 用空对象为此历史精确键覆盖共享规则。
            rules.exact[model_id] = tariff_rule(prices) or vulcan.json.object()
        end
    end
end

-- Build schedule maps from catalog quotes and overrides for SQL and per-request estimates.
-- 从目录报价和用户覆盖构建供 SQL 与逐请求估算使用的时段映射。
local function pricing_rules(overrides)
    -- An empty rule shadows less specific windows when the selected price is flat.
    -- 所选价格为单一费率时，空规则屏蔽优先级较低的时段。
    local rules = { shared = vulcan.json.object(), providers = vulcan.json.object(),
        userShared = { shared = vulcan.json.object(), exact = vulcan.json.object() },
        providerRefs = vulcan.json.object(), entryRefs = vulcan.json.object() }
    for model_id, prices in pairs(DEFAULT_PRICING_CATALOG.models) do
        rules.shared[model_id] = tariff_rule(prices)
    end
    add_override_rules(rules.userShared, overrides.shared)
    for provider_id, models in pairs(DEFAULT_PRICING_CATALOG.provider_models) do
        rules.providers[provider_id] = { shared = vulcan.json.object(), exact = vulcan.json.object() }
        rules.providerRefs[provider_id] = vulcan.json.object()
        for model_id, prices in pairs(models) do
            rules.providerRefs[provider_id][model_id] = tariff_rule(prices) or vulcan.json.object()
        end
    end
    for provider_id, entries in pairs(DEFAULT_PRICING_CATALOG.provider_entry_models) do
        rules.entryRefs[provider_id] = vulcan.json.object()
        for entry_id, models in pairs(entries) do
            rules.entryRefs[provider_id][entry_id] = vulcan.json.object()
            for model_id, prices in pairs(models) do
                rules.entryRefs[provider_id][entry_id][model_id] = tariff_rule(prices) or vulcan.json.object()
            end
        end
    end
    for provider_id, scope in pairs(overrides.providers) do
        -- Keeping the provider as a separate key avoids combining models served by different providers.
        -- 单独使用供应商作为键，避免合并由不同供应商提供的模型。
        local provider_rules = { shared = vulcan.json.object(), exact = vulcan.json.object() }
        add_override_rules(provider_rules, scope)
        rules.providers[provider_id] = provider_rules
    end
    return rules
end

-- Return a regional or provider reference for the exact upstream suffix, then its billing family.
-- 先按上游精确后缀、再按定价系列查找地区或供应商报价。
-- maps are keyed by provider and optional service entry; the result is a price or schedule.
-- maps 按供应商和可选服务入口索引；返回价格或时段规则。
local function scoped_catalog_value(provider_refs, entry_refs, provider_id, entry_id, model_id, canonical)
    -- Preserve differently priced snapshots before consulting shared model aliases.
    -- 优先保留独立定价的快照，再查找共享模型别名。
    local suffix = (model_id:match("[^/]+$") or model_id):lower()
    local entries = entry_refs[provider_id]
    local regional = entries and entries[entry_id]
    local provider = provider_refs[provider_id]
    return (regional and (regional[suffix] or regional[canonical]))
        or (provider and (provider[suffix] or provider[canonical]))
end

-- Report whether this raw model's recorded terminal time falls in an off-peak interval.
-- 判断原始模型记录的终止时间是否落在谷价时段内。
local function is_off_peak(provider_id, entry_id, model_id, terminal_at_ms, rules)
    -- The exact map contains only legacy conflicts; other matches use the canonical map.
    -- 精确映射只含历史冲突，其余匹配使用定价主标识映射。
    local canonical = billing_model_id(model_id)
    local provider = rules.providers[provider_id]
    local rule = provider and (provider.exact[model_id] or provider.shared[provider_billing_model_id(model_id, provider_id)])
    if rule == nil then rule = rules.userShared.exact[model_id] or rules.userShared.shared[canonical] end
    if rule == nil then
        rule = scoped_catalog_value(rules.providerRefs, rules.entryRefs, provider_id, entry_id, model_id, canonical)
            or rules.shared[canonical]
    end
    if rule == nil or rule.windows == nil then return false end
    local minute = (math.floor(terminal_at_ms / MILLISECONDS_PER_MINUTE) + UNIX_EPOCH_WEEK_MINUTE) % WEEK_MINUTES
    for _, interval in ipairs(rule.windows) do
        if interval.lower <= minute and minute < interval.upper then return true end
    end
    return false
end

-- Divide price by the positive CNY-per-USD rate and return the rounded USD decimal.
-- 用人民币单价除以正汇率，返回舍入后的美元十进制单价。
local function price_in_usd(price, rate_digits, rate_scale)
    -- Keep at least twelve extra fractional digits after accounting for the divisor width.
    -- 计入除数位宽后仍保留至少十二位额外小数。
    local digits, scale = parse_catalog_decimal(price)
    local precision = #rate_digits + 12
    local numerator = digits .. string.rep("0", precision + rate_scale)
    -- The rate schema keeps each remainder and next digit below the exact Lua number limit.
    -- 汇率 Schema 将每步余数和补入的一位限制在 Lua 数值精确表示范围内。
    local divisor = tonumber(rate_digits)
    local remainder, quotient = 0, {}
    for index = 1, #numerator do
        -- Long division never converts the input price to a binary floating-point value.
        -- 长除法始终保留输入单价，不将其转换成二进制浮点数。
        local step = remainder * 10 + tonumber(numerator:sub(index, index))
        local digit = math.floor(step / divisor)
        quotient[index] = tostring(digit)
        remainder = step - digit * divisor
    end
    -- Round half up at the final computed decimal place.
    -- 在最终计算小数位进行四舍五入。
    local result = table.concat(quotient)
    if remainder * 2 >= divisor then
        result = add_unsigned_integers(result, "1")
    end
    return format_scaled_decimal(result, scale + precision)
end

-- Default CNY per USD applies to every model and provider without writing a setting.
-- 默认的每美元人民币金额适用于所有模型及供应商，并且不写入设置。
local DEFAULT_CNY_PER_USD = "6.7"

-- Resolve missing sides of each explicit price pair using the captured rate.
-- 用固定汇率解析每对显式单价中缺失的一侧。
-- Returns effective rates grouped by currency for a base or off-peak price set.
-- 返回按币种分组的基础价或谷价生效单价。
local function effective_prices(explicit, config)
    -- Calculate both currencies from the single rate captured for the pricing request.
    -- 使用为本次定价请求获取的统一汇率计算两个币种。
    local effective = { USD = vulcan.json.object(), CNY = vulcan.json.object() }
    local rate_digits, rate_scale = parse_catalog_decimal(config.cnyPerUsd or DEFAULT_CNY_PER_USD)
    for _, dimension in ipairs(PRICE_DIMENSIONS) do
        local usd, cny = explicit[dimension.usd], explicit[dimension.cny]
        -- Only an empty side is derived. Explicit zero also takes precedence.
        -- 只折算留空的一侧，显式填写的零也优先。
        if usd == nil then
            usd = price_in_usd(cny, rate_digits, rate_scale)
        elseif cny == nil then
            local digits, scale = parse_catalog_decimal(usd)
            cny = format_scaled_decimal(multiply_unsigned_integers(digits, rate_digits), scale + rate_scale)
        end
        effective.USD[dimension.usd], effective.CNY[dimension.usd] = usd, cny
    end
    return effective
end

-- Resolve a model override and its stored key within one provider or shared scope.
-- 在单个供应商或共享范围内解析模型覆盖和对应的存储键。
local function scope_override(scope, model_id, canonical)
    -- For conflicted groups, only the original exact key can supply a user override.
    -- 对于冲突组，只有原始精确键能提供用户覆盖价。
    local group = scope.groups[canonical]
    if group ~= nil and not group.conflict then return group.prices, canonical end
    return scope.prices[model_id], model_id
end

-- Resolve a model's editable price, effective rates, source and override key.
-- 解析模型的可编辑单价、生效价格、来源及覆盖键。
local function model_prices(model_id, config, overrides, provider_id, entry_id)
    -- A provider-specific price wins over the shared override and catalog for the same model.
    -- 同一模型的供应商专属价格优先于共享覆盖和目录。
    local canonical = billing_model_id(model_id)
    local provider = overrides.providers[provider_id]
    if provider ~= nil then
        local price, key = scope_override(provider, model_id, provider_billing_model_id(model_id, provider_id))
        if price ~= nil then return price, effective_prices(price, config), "provider_override", key end
    end
    local explicit, key = scope_override(overrides.shared, model_id, canonical)
    if explicit ~= nil then return explicit, effective_prices(explicit, config), "override", key end
    -- Consult the provider's reference only after both user override scopes.
    -- 两级用户覆盖都未命中时，才查找供应商参考价。
    local provider_catalog = scoped_catalog_value(DEFAULT_PRICING_CATALOG.provider_models,
        DEFAULT_PRICING_CATALOG.provider_entry_models, provider_id, entry_id, model_id, canonical)
    if provider_catalog ~= nil then return provider_catalog, effective_prices(provider_catalog, config), "catalog" end
    -- Reference prices are keyed by canonical billing model IDs.
    -- 参考价以定价主模型标识作为键。
    local catalog = DEFAULT_PRICING_CATALOG.models[canonical]
    if catalog == nil then return nil, vulcan.json.object(), "unpriced" end
    return catalog, effective_prices(catalog, config), "catalog"
end

-- Report whether prices provides every Token dimension in a single currency.
-- 判断 prices 是否提供单一币种的全部 Token 维度单价。
local function currency_has_prices(prices)
    if prices == nil then return false end
    for _, dimension in ipairs(PRICE_DIMENSIONS) do
        if prices[dimension.usd] == nil then return false end
    end
    return true
end

-- Estimate one currency from row at the selected time and context rate.
-- 使用所选时段和上下文档位的单价估算 row 的单币种费用。
-- Returns the known subtotal and coverage, or nil for an unpriced currency.
-- 返回已知小计及覆盖情况，币种未定价时返回 nil。
local function estimate_currency(row, prices, currency, off_peak, above_input_tokens)
    if not currency_has_prices(prices) then return nil end
    -- details tracks the component amounts independently from complete and partial coverage.
    -- details 记录分项金额，并与完整和部分覆盖状态分开保存。
    local details = { currency = currency, dimensions = vulcan.json.array() }
    local total_digits, total_scale = "0", 0
    -- Track gaps separately from evidence that a subtotal can be calculated.
    -- 分开记录用量缺口和可计算小计的依据。
    local missing, has_priced_usage = false, false
    for _, dimension in ipairs(PRICE_DIMENSIONS) do
        -- Keep each exact amount tied to its source Token fact and applicable rate.
        -- 将每个精确金额与相应 Token 事实和适用费率绑定。
        local price = prices[dimension.usd]
        local price_digits, price_scale = parse_catalog_decimal(price)
        local tokens = token_digits(row[dimension.tokens])
        local cost = vulcan.json.null
        if price_digits ~= "0" and tokens == nil then
            missing = true
        else
            -- A known amount at a nonzero rate is evidence for displaying a partial subtotal.
            -- 非零费率下已知的用量可以作为显示部分小计的依据。
            has_priced_usage = has_priced_usage or price_digits ~= "0"
            -- A missing free dimension contributes exactly zero and does not reduce coverage.
            -- 免费维度即使用量缺失也恰好计零，且不影响覆盖率。
            local digits = multiply_unsigned_integers(tokens or "0", price_digits)
            local scale = price_scale + 6
            cost = format_scaled_decimal(digits, scale)
            local next_scale = math.max(total_scale, scale)
            total_digits = add_unsigned_integers(
                total_digits .. string.rep("0", next_scale - total_scale),
                digits .. string.rep("0", next_scale - scale)
            )
            total_scale = next_scale
        end
        missing = missing or (price_digits ~= "0" and row[dimension.tokens .. "Missing"] == 1)
        details.dimensions[#details.dimensions + 1] = {
            tokenField = dimension.tokens, perMillion = price, cost = cost, offPeak = off_peak,
            aboveInputTokens = above_input_tokens,
        }
    end
    details.hasPartialUsage = missing
    return {
        amount = (not missing or has_priced_usage) and format_scaled_decimal(total_digits, total_scale) or vulcan.json.null,
        details = details,
    }
end

-- Add a decimal amount to an exact scaled total in place.
-- 将十进制金额原地加入精确的缩放总额。
local function add_cost(total, amount)
    -- Scale both exact integer components before summing their decimal amounts.
    -- 累加十进制金额前，先对齐两项精确整数的小数位。
    local digits, scale = parse_catalog_decimal(amount)
    local next_scale = math.max(total.scale, scale)
    total.digits = add_unsigned_integers(
        total.digits .. string.rep("0", next_scale - total.scale),
        digits .. string.rep("0", next_scale - scale)
    )
    total.scale = next_scale
end

-- Resolve each context tier from explicit prices into the two effective currencies.
-- 将各上下文档位的显式单价解析为两种生效币种的费率。
-- tiers is optional; returns rates keyed by each exclusive lower input bound.
-- tiers 可省略；返回以各档位排他性输入下限为键的费率。
local function effective_context_tiers(tiers, config)
    -- A threshold keys the same price for grouped SQL buckets and single requests.
    -- 同一个阈值为 SQL 用量桶和逐请求匹配到相同单价。
    local effective = {}
    for _, tier in ipairs(tiers or EMPTY_ARRAY) do
        effective[tier.aboveInputTokens] = effective_prices(tier.prices, config)
    end
    return effective
end

-- Select the highest exceeded threshold for a single request.
-- 为单次请求选择已超过的最高阈值。
-- Returns 0 for the base rate and -1 if missing input prevents tier selection.
-- 基础价返回 0，输入用量缺失导致无法选档时返回 -1。
local function request_context_threshold(tiers, input_tokens)
    if next(tiers) == nil then return 0 end
    if input_tokens == nil or input_tokens == vulcan.json.null then return -1 end
    -- Keep this comparison identical to the aggregate SQL's exclusive lower bound.
    -- 这里与聚合 SQL 使用同样的排他性下限比较。
    local threshold = 0
    for lower_bound in pairs(tiers) do
        if input_tokens > lower_bound then threshold = math.max(threshold, lower_bound) end
    end
    return threshold
end

-- Estimate one request or aggregate bucket using its selected threshold and time tariff.
-- 使用已选阈值和时段费率估算单次请求或聚合用量桶。
-- A missing tier input returns incomplete usage for any currency with a complete candidate rate.
-- 档位输入缺失时，对有完整候选费率的币种返回用量不完整。
local function estimate_tariff_bucket(row, tariff, currency, off_peak, threshold)
    if threshold == -1 then
        -- Preserve unknown input without assigning a cheaper or more expensive tier.
        -- 保留输入未知的状态，避免套用较低或较高档位。
        local priced = currency_has_prices(tariff.prices[currency])
        for _, prices in pairs(tariff.tiers) do
            priced = priced or currency_has_prices(prices[currency])
        end
        if priced then
            return { amount = vulcan.json.null, details = {
                currency = currency, dimensions = vulcan.json.array(), hasPartialUsage = true,
            } }
        end
        return nil
    end
    if threshold == 0 then return estimate_currency(row, tariff.prices[currency], currency, off_peak) end
    return estimate_currency(row, tariff.tiers[threshold][currency], currency, off_peak, threshold)
end

-- Estimate one currency across time and context buckets without averaging unit prices.
-- 分开估算时段和上下文用量桶中的一个币种，避免对单价取平均。
-- Returns the known subtotal and coverage across the buckets, or nil if unpriced.
-- 返回各用量桶的已知小计和覆盖情况，未定价时返回 nil。
local function estimate_tariffs(row, model, currency, tariff_usage)
    if tariff_usage == nil then
        -- Only individual requests can select a tier from this row's input tokens.
        -- 只有逐请求记录可以用此行的输入用量选档。
        local tariff = model.base
        if row.isOffPeak then tariff = model.off_peak end
        local threshold = row.terminalAtMs ~= nil and request_context_threshold(tariff.tiers, row.inputTokens) or 0
        return estimate_tariff_bucket(row, tariff, currency, row.isOffPeak or nil, threshold)
    end
    -- combined contains one currency's detailed rows and its own accumulator.
    -- combined 包含一个币种的费用明细，其金额独立累加。
    local combined = { details = { currency = currency, dimensions = vulcan.json.array(), hasPartialUsage = false } }
    local total = { digits = "0", scale = 0 }
    -- Track whether any bucket contributed a known amount, including an observed zero.
    -- 记录是否有用量桶贡献了已知金额，包括实际观测到的零值。
    local has_amount = false
    for _, bucket in ipairs(tariff_usage) do
        -- Choose the rate belonging to this timestamp bucket before estimating usage.
        -- 先选择该时间戳用量桶的对应费率，再估算费用。
        local off_peak = bucket.isOffPeak == 1
        local tariff = model.base
        if off_peak then tariff = model.off_peak end
        local estimate = estimate_tariff_bucket(bucket, tariff, currency, off_peak, bucket.contextThreshold)
        -- An unknown tariff price leaves the currency unpriced for the aggregate row.
        -- 时段单价缺失时，整条聚合行在该币种下标记为未定价。
        if estimate == nil then return nil end
        if estimate.amount ~= vulcan.json.null then
            has_amount = true
            add_cost(total, estimate.amount)
        end
        combined.details.hasPartialUsage = combined.details.hasPartialUsage or estimate.details.hasPartialUsage
        for _, dimension in ipairs(estimate.details.dimensions) do
            combined.details.dimensions[#combined.details.dimensions + 1] = dimension
        end
    end
    combined.amount = has_amount and format_scaled_decimal(total.digits, total.scale) or vulcan.json.null
    return combined
end

-- Estimate both currencies for a usage row using the action's captured pricing configuration.
-- 根据本次 Action 固定的定价配置为用量行估算两种币种。
--
-- row contains the token-only core projection.
-- row 包含仅 Token 的核心投影。
-- config holds the exchange rate; cache reuses effective prices within the same provider and model.
-- config 持有汇率；cache 在相同供应商和模型范围内复用生效价格。
-- Updates the row and returns estimates with their coverage keyed by currency.
-- 更新用量行，并返回以币种为键、包含覆盖情况的估算。
local function attach_reference_estimate(row, config, cache, overrides)
    -- Reuse converted rates only within a provider and regional scope.
    -- 折算后的单价只在同一供应商与地区范围内复用。
    local scope_id = (overrides.providers[row.providerId] or DEFAULT_PRICING_CATALOG.provider_models[row.providerId])
        and row.providerId or ""
    if cache[scope_id] == nil then cache[scope_id] = {} end
    local regional = DEFAULT_PRICING_CATALOG.provider_entry_models[row.providerId]
    local entry_key = regional and regional[row.serviceEntryId] and row.serviceEntryId or ""
    if cache[scope_id][entry_key] == nil then cache[scope_id][entry_key] = {} end
    local scope_cache = cache[scope_id][entry_key]
    local model = scope_cache[row.modelId]
    if model == nil then
        local explicit, effective, source, source_model = model_prices(row.modelId, config, overrides, row.providerId, row.serviceEntryId)
        model = { base = { prices = effective, tiers = effective_context_tiers(explicit and explicit.contextTiers, config) }, source = source }
        if source == "catalog" then
            model.revision = DEFAULT_PRICING_CATALOG.revision
            model.source_id = DEFAULT_PRICING_CATALOG.catalog_id
        elseif source == "override" then
            model.revision = "plugin-config-v2:" .. source_model .. ":" .. price_signature(explicit)
            model.source_id = "plugin.config.modelOverrides:" .. source_model
        elseif source == "provider_override" then
            -- Encode both keys unambiguously even if a custom identifier contains delimiters.
            -- 即使自定义标识包含分隔符，也能明确编码两个键。
            local binding = vulcan.json.encode(vulcan.json.array({ row.providerId, source_model }))
            model.revision = "plugin-provider-config-v1:" .. binding .. ":" .. price_signature(explicit)
            model.source_id = "plugin.config.providerOverrides:" .. binding
        end
        if explicit ~= nil and explicit.offPeak ~= nil then
            model.off_peak = {
                prices = effective_prices(explicit.offPeak.prices, config),
                tiers = effective_context_tiers(explicit.offPeak.contextTiers, config),
            }
        end
        if model.revision ~= nil then
            model.revision = model.revision .. ":cnyPerUsd:" .. (config.cnyPerUsd or DEFAULT_CNY_PER_USD)
        end
        scope_cache[row.modelId] = model
    end

    -- SQL supplies tariff buckets only when the aggregate includes off-peak requests.
    -- 仅当聚合包含谷价请求时，SQL 才提供时段用量桶。
    local tariff_usage
    if row.tariffUsageJson ~= nil and row.tariffUsageJson ~= vulcan.json.null then
        tariff_usage = decode_json_text(row.tariffUsageJson, "tariffUsageJson")
    end
    local usd = estimate_tariffs(row, model, "USD", tariff_usage)
    local cny = estimate_tariffs(row, model, "CNY", tariff_usage)
    row.tariffUsageJson, row.isOffPeak = nil, nil
    -- Keep the existing primary estimate fields usable for USD-only and CNY-only rows.
    -- 让现有主估算字段同时支持仅美元和仅人民币的行。
    local primary = usd or cny
    row.estimatedCost = primary and primary.amount or vulcan.json.null
    row.estimatedCurrency = primary and primary.amount ~= vulcan.json.null and primary.details.currency or vulcan.json.null
    row.pricingDetails = primary and primary.details or vulcan.json.null
    row.pricingRevision = model.revision or vulcan.json.null
    row.pricingSourceId = model.source_id or vulcan.json.null
    if primary == nil then
        row.pricingMatchStatus = "unmatched"
    elseif primary.details.hasPartialUsage then
        row.pricingMatchStatus = "incomplete_usage"
    else
        row.pricingMatchStatus = model.source == "catalog" and "catalog_exact" or "override_exact"
    end
    if usd ~= nil and cny ~= nil then row.alternateEstimate = cny end
    return { USD = usd, CNY = cny }
end

-- Count exact model overrides without depending on Lua table iteration order.
-- 统计精确模型覆盖数量，且不依赖 Lua 表迭代顺序。
--
-- config holds shared model overrides and optional provider maps.
-- config 保存共享模型覆盖及可选的供应商覆盖映射。
-- Returns the number of configured model prices across all scopes.
-- 返回所有范围内配置的模型价格数量。
local function model_override_count(config)
    local count = 0
    for _ in pairs(config.modelOverrides) do
        count = count + 1
    end
    for _, prices in pairs(config.providerOverrides or {}) do
        for _ in pairs(prices) do count = count + 1 end
    end
    return count
end

-- Project plugin settings together with the sorted default catalog model list.
-- 投影插件设置以及排序后的默认目录模型列表。
--
-- config is the complete schema-validated plugin configuration.
-- config 是完整且通过 Schema 校验的插件配置。
-- Returns the settings action result consumed by the mounted UI.
-- 返回挂载界面消费的设置 Action 结果。
local function settings_projection(config)
    local catalog_models = vulcan.json.array()
    for model_id, pricing in pairs(DEFAULT_PRICING_CATALOG.models) do
        catalog_models[#catalog_models + 1] = {
            modelId = model_id,
            prices = pricing,
        }
    end
    table.sort(catalog_models, function(left, right)
        return left.modelId < right.modelId
    end)
    return {
        modelOverrides = config.modelOverrides,
        providerOverrides = config.providerOverrides,
        catalogModels = catalog_models,
        providerCatalogModels = DEFAULT_PRICING_CATALOG.provider_models,
        cnyPerUsd = config.cnyPerUsd,
        defaultCnyPerUsd = DEFAULT_CNY_PER_USD,
        modelAliases = DECLARED_MODEL_ALIASES,
        modelPrefixes = DECLARED_MODEL_PREFIXES,
    }
end

-- Load the authoritative Provider usage dashboard directly from system VLDB.
-- 直接从系统 VLDB 加载权威 Provider 用量仪表盘。
--
-- input selects the validated time range, filters, view and page offsets.
-- input 选择已校验的时间范围、筛选条件、视图和分页偏移。
-- config and price_cache hold the captured pricing configuration and its resolved model prices.
-- config 与 price_cache 持有本次固定的定价配置和已解析的模型价格。
-- Returns the projection, or nil and the projection kind if the aggregate revision changes.
-- 返回统计投影；若聚合版本发生变化，则返回 nil 和投影类别。
local function load_dashboard(input, config, price_cache, overrides, rules)
    -- view selects required projections; omitted arguments retain the complete legacy response.
    -- view 选择所需投影；参数省略时保留完整旧响应。
    local view = input.view or "all"
    -- Page projections read only their requested table and count, retaining the revision guard.
    -- 分页投影仅读取请求的表格及数量，并保留修订一致性检查。
    local page_only = view == "daily-page" or view == "recent-page" or view == "detail-pages"
    -- Only views with recent rows need the full list of eligible models.
    -- 仅包含最近请求记录的视图需要完整的可选模型列表。
    local include_recent = view == "all" or view == "details" or view == "recent" or view == "recent-page" or view == "detail-pages"
    -- The input schema requires both IDs whenever a recent model is selected.
    -- 选择最近请求模型时，输入 Schema 要求同时提供两个标识。
    local recent_model = input.recentModel
    -- known_models bounds cost aggregation to catalog and configured model identities.
    -- known_models 将费用聚合限制在目录与已配置模型身份内。
    local known_models = {}
    for model_id in pairs(DEFAULT_PRICING_CATALOG.models) do known_models[model_id] = true end
    for _, models in pairs(DEFAULT_PRICING_CATALOG.provider_models) do
        for model_id in pairs(models) do known_models[billing_model_id(model_id)] = true end
    end
    for model_id in pairs(overrides.shared.groups) do known_models[model_id] = true end
    for _, scope in pairs(overrides.providers) do
        for model_id in pairs(scope.groups) do known_models[model_id] = true end
    end
    -- priced_model_ids contains at most the catalog size plus the schema-limited override count.
    -- priced_model_ids 最多包含目录规模加 Schema 限制的覆盖数量。
    local priced_model_ids = vulcan.json.array()
    for model_id in pairs(known_models) do priced_model_ids[#priced_model_ids + 1] = model_id end
    -- filter_params bind the optional bounded range and exact consumer without SQL interpolation.
    -- filter_params 绑定可选有界范围与精确消费者，不进行 SQL 插值。
    local filter_params = {
        { kind = "int64", value = input.rangeDays or 365 },
        { kind = "string", value = input.consumerId or "" },
        { kind = "int64", value = input.dailyOffset or 0 },
        { kind = "int64", value = input.recentOffset or 0 },
        { kind = "string", value = input.modelQuery or "" },
        { kind = "string", value = input.sortOrder or "newest" },
        { kind = "string", value = vulcan.json.encode(priced_model_ids) },
        { kind = "int64", value = 0 },
        -- Select recent model pages before counting or applying the page limit; omitted callers keep all types.
        -- 在计数与分页截取之前选择最近调用的模型类别；省略参数的调用方保留全部类型。
        { kind = "string", value = input.recentModelType or "all" },
        -- Zero denotes an omitted legacy bound; explicit inputs are positive Unix milliseconds.
        -- 零表示旧调用省略边界；显式输入为正 Unix 毫秒数。
        { kind = "int64", value = input.startAtMs or 0 },
        { kind = "int64", value = input.endAtMs or 0 },
        -- An empty Provider keeps every Provider; the Provider list itself ignores this filter.
        -- 空 Provider 保留全部 Provider；Provider 列表本身不应用此筛选。
        { kind = "string", value = input.providerId or "" },
        { kind = "string", value = billing_lookup_json() },
        { kind = "string", value = vulcan.json.encode(rules) },
        { kind = "string", value = recent_model and recent_model.providerId or "" },
        { kind = "string", value = recent_model and recent_model.modelId or "" },
    }
    -- Flat-rate models keep the original aggregate path.
    -- 单一费率模型保留原聚合路径。
    local tariff_sql = [[
, tariff_groups AS (
    SELECT provider_id, service_entry_id, consumer_id, operation, model_id, NULL AS tariffUsageJson
    FROM range_usage WHERE 0
)
]]
    if next(rules.shared) ~= nil or next(rules.userShared.exact) ~= nil or next(rules.userShared.shared) ~= nil
        or next(rules.providers) ~= nil then
        -- Classify each original request before grouping Token quantities.
        -- 在汇总 Token 数量之前，先对每条原始请求选档。
        local minute = "((CAST(a.terminal_at_ms / " .. MILLISECONDS_PER_MINUTE .. " AS INTEGER) + " ..
            UNIX_EPOCH_WEEK_MINUTE .. ") % " .. WEEK_MINUTES .. " + " .. WEEK_MINUTES .. ") % " .. WEEK_MINUTES
        tariff_sql = [[
, tariff_identities AS MATERIALIZED (
    SELECT provider_id, service_entry_id, raw_model, lower(]] .. model_id_suffix_sql("raw_model") .. [[) AS suffix,
           ]] .. billing_model_sql("raw_model") .. [[ AS canonical
    FROM (SELECT DISTINCT provider_id, service_entry_id, mapped_model AS raw_model FROM filtered_attempts)
), tariff_models AS MATERIALIZED (
    SELECT m.provider_id, m.service_entry_id, m.raw_model,
           COALESCE((SELECT value FROM json_each(p.value, '$.exact') WHERE key = m.raw_model),
                    (SELECT value FROM json_each(p.value, '$.shared') WHERE key =
                        COALESCE((SELECT key FROM json_each(r.value) WHERE key = m.suffix), m.canonical)),
                    (SELECT value FROM json_each(?14, '$.userShared.exact') WHERE key = m.raw_model),
                    (SELECT value FROM json_each(?14, '$.userShared.shared') WHERE key = m.canonical),
                    (SELECT value FROM json_each(e.value) WHERE key = m.suffix),
                    (SELECT value FROM json_each(e.value) WHERE key = m.canonical),
                    (SELECT value FROM json_each(r.value) WHERE key = m.suffix),
                    (SELECT value FROM json_each(r.value) WHERE key = m.canonical),
                    (SELECT value FROM json_each(?14, '$.shared') WHERE key = m.canonical)) AS rule
    FROM tariff_identities m
    LEFT JOIN json_each(?14, '$.providers') p ON p.key = m.provider_id
    LEFT JOIN json_each(?14, '$.providerRefs') r ON r.key = m.provider_id
    LEFT JOIN json_each(?14, '$.entryRefs') entries ON entries.key = m.provider_id
    LEFT JOIN json_each(entries.value) e ON e.key = m.service_entry_id
), tariff_candidates AS (
    SELECT a.provider_id, a.service_entry_id, a.consumer_id, a.operation, a.mapped_model AS model_id,
           a.input_tokens, a.uncached_input_tokens, a.cache_read_tokens, a.cache_write_tokens, a.output_tokens, m.rule,
           EXISTS (SELECT 1 FROM json_each(m.rule, '$.windows') w
                   WHERE ]] .. minute .. [[ >= json_extract(w.value, '$.lower')
                     AND ]] .. minute .. [[ < json_extract(w.value, '$.upper')) AS is_off_peak
    FROM filtered_attempts a JOIN tariff_models m ON m.provider_id = a.provider_id
      AND m.service_entry_id = a.service_entry_id AND m.raw_model = a.mapped_model
    WHERE m.rule IS NOT NULL
), tariff_thresholds AS (
    SELECT *, CASE WHEN is_off_peak = 1 THEN '$.offPeakThresholds' ELSE '$.baseThresholds' END AS thresholds_path
    FROM tariff_candidates
), tariff_selected AS (
    SELECT a.*,
           CASE WHEN a.input_tokens IS NULL AND json_type(a.rule, a.thresholds_path) = 'array' THEN -1
                ELSE COALESCE((SELECT MAX(value) FROM json_each(a.rule, a.thresholds_path)
                               WHERE a.input_tokens > value), 0) END AS context_threshold
    FROM tariff_thresholds a
), tariff_buckets AS (
    SELECT a.provider_id, a.service_entry_id, a.consumer_id, a.operation, a.model_id, a.is_off_peak, a.context_threshold,
           SUM(a.uncached_input_tokens) AS input_tokens, SUM(a.cache_read_tokens) AS read_tokens,
           SUM(a.cache_write_tokens) AS write_tokens, SUM(a.output_tokens) AS output_tokens,
           COUNT(*) > COUNT(a.uncached_input_tokens) AS input_missing,
           COUNT(*) > COUNT(a.cache_read_tokens) AS read_missing,
           COUNT(*) > COUNT(a.cache_write_tokens) AS write_missing,
           COUNT(*) > COUNT(a.output_tokens) AS output_missing
    FROM tariff_selected a
    GROUP BY a.provider_id, a.service_entry_id, a.consumer_id, a.operation, a.model_id, a.is_off_peak, a.context_threshold
), tariff_groups AS (
    SELECT provider_id, service_entry_id, consumer_id, operation, model_id,
           json_group_array(json_object('isOffPeak', is_off_peak, 'contextThreshold', context_threshold, 'uncachedInputTokens', input_tokens,
               'cacheReadTokens', read_tokens, 'cacheWriteTokens', write_tokens, 'outputTokens', output_tokens,
               'uncachedInputTokensMissing', input_missing, 'cacheReadTokensMissing', read_missing,
               'cacheWriteTokensMissing', write_missing, 'outputTokensMissing', output_missing)) AS tariffUsageJson
    FROM tariff_buckets
    GROUP BY provider_id, service_entry_id, consumer_id, operation, model_id
    HAVING MAX(is_off_peak) = 1 OR MIN(context_threshold) < 0 OR MAX(context_threshold) > 0
)
]]
    end
    -- query binds one shared filter contract to every dashboard projection.
    -- query 为每个仪表盘投影绑定同一个筛选契约。
    -- sql is fixed source SQL; returns decoded rows from the system database.
    -- sql 是固定源码 SQL；返回系统数据库中的已解码行。
    local function query(sql)
        return sqlite_query([[
WITH ]] .. billing_lookup_sql("?13") .. [[,
scoped_attempts AS (
    SELECT *, ]] .. KNOWN_TOTAL_TOKENS_SQL .. [[ AS known_total_tokens
    FROM provider_usage_attempts_v3
    WHERE terminal_at_ms >= CASE WHEN ?10 > 0 THEN ?10
      ELSE CAST(strftime('%s', date('now', 'localtime', '-' || (?1 - 1) || ' days'), 'utc') AS INTEGER) * 1000 END
      AND (?11 = 0 OR terminal_at_ms <= ?11)
      AND (?2 = '' OR consumer_id = ?2)
      AND (?5 = '' OR instr(lower(mapped_model), lower(?5)) > 0)
), filtered_attempts AS (
    SELECT * FROM scoped_attempts WHERE ?12 = '' OR provider_id = ?12
), filtered_daily AS (
    SELECT calendar_date, provider_id, service_entry_id, consumer_id, operation, mapped_model AS model_id,
      COUNT(*) AS attempt_count,
      SUM(CASE WHEN status = 'succeeded' THEN 1 ELSE 0 END) AS successful_attempt_count,
      SUM(CASE WHEN usage_availability IN ('partial', 'final') THEN 1 ELSE 0 END) AS reported_usage_attempt_count,
      SUM(input_tokens) AS input_tokens, SUM(uncached_input_tokens) AS uncached_input_tokens,
      SUM(cache_read_tokens) AS cache_read_tokens, SUM(cache_write_tokens) AS cache_write_tokens,
      SUM(output_tokens) AS output_tokens, SUM(reasoning_tokens) AS reasoning_tokens, SUM(known_total_tokens) AS total_tokens,
      COUNT(*) - COUNT(uncached_input_tokens) AS uncached_input_missing,
      COUNT(*) - COUNT(cache_read_tokens) AS cache_read_missing,
      COUNT(*) - COUNT(cache_write_tokens) AS cache_write_missing,
      COUNT(*) - COUNT(output_tokens) AS output_missing
    FROM filtered_attempts
    GROUP BY calendar_date, provider_id, service_entry_id, consumer_id, operation, mapped_model
), range_usage AS (
    SELECT provider_id, service_entry_id, consumer_id, operation, model_id,
      SUM(attempt_count) AS attempt_count, SUM(successful_attempt_count) AS successful_attempt_count,
      SUM(reported_usage_attempt_count) AS reported_usage_attempt_count,
      SUM(input_tokens) AS input_tokens, SUM(uncached_input_tokens) AS uncached_input_tokens,
      SUM(cache_read_tokens) AS cache_read_tokens, SUM(cache_write_tokens) AS cache_write_tokens,
      SUM(output_tokens) AS output_tokens, SUM(reasoning_tokens) AS reasoning_tokens, SUM(total_tokens) AS total_tokens,
      SUM(uncached_input_missing) AS uncached_input_missing, SUM(cache_read_missing) AS cache_read_missing,
      SUM(cache_write_missing) AS cache_write_missing, SUM(output_missing) AS output_missing,
      MAX(calendar_date) AS latest_date
    FROM filtered_daily
    GROUP BY provider_id, service_entry_id, consumer_id, operation, model_id
), timed_attempts AS (
    SELECT *,
      CASE WHEN terminal_at_ms >= dispatched_at_ms THEN terminal_at_ms - dispatched_at_ms END AS request_duration_ms,
      CASE WHEN first_token_at_ms >= dispatched_at_ms AND terminal_at_ms >= first_token_at_ms
        THEN first_token_at_ms - dispatched_at_ms END AS first_token_latency_ms,
      CASE WHEN first_token_at_ms >= dispatched_at_ms AND terminal_at_ms >= first_token_at_ms
        THEN terminal_at_ms - first_token_at_ms END AS output_duration_ms
    FROM filtered_attempts
), recent_model_scope AS (
    SELECT * FROM timed_attempts
    WHERE ?9 = 'all'
       OR (?9 = 'llm' AND operation IN ('conversation', 'conversation_respond', 'compact', 'warmup')
           AND consumer_id NOT IN ('vulcan-code-permission-judge', 'vulcan-code-permission-review'))
       OR (?9 = 'embedding' AND operation = 'embedding_create')
       OR (?9 = 'rerank' AND operation = 'rerank_documents')
       OR (?9 = 'decision' AND (operation = 'decision_evaluate'
           OR consumer_id IN ('vulcan-code-permission-judge', 'vulcan-code-permission-review')))
), recent_model_attempts AS (
    SELECT * FROM recent_model_scope
    WHERE ?15 = '' OR (provider_id = ?15 AND mapped_model = ?16)
), page_offsets AS (SELECT ?3 AS daily_offset, ?4 AS recent_offset, ?6 AS sort_order, ?7 AS priced_models, ?8 AS cost_offset,
                          ?13 AS model_aliases, ?14 AS tariff_windows)
]] .. sql, filter_params)
    end
    -- Open the revision window just before the first data query, after preparing filters.
    -- 在筛选条件准备完毕后、首次数据查询前开启版本检查窗口。
    local initial_revision_rows = sqlite_query([[
SELECT COALESCE(MAX(CAST(meta_value AS INTEGER)), 0) AS dashboardRevision
FROM provider_usage_meta WHERE meta_key = 'aggregate_revision';
]])
    -- initial_revision identifies the host commit used to validate the following reads.
    -- initial_revision 标识用于校验后续读取的宿主提交版本。
    local initial_revision = initial_revision_rows[1].dashboardRevision
    local daily = (view == "all" or view == "details" or view == "providers" or view == "daily-page" or view == "detail-pages") and query(tariff_sql .. [[
, daily_timing AS (
    SELECT provider_id, service_entry_id, consumer_id, operation, mapped_model AS model_id,
      AVG(request_duration_ms) AS requestDurationMs,
      AVG(first_token_latency_ms) AS firstTokenLatencyMs,
      SUM(CASE WHEN output_duration_ms > 0 AND output_tokens IS NOT NULL THEN output_duration_ms END) AS outputDurationMs,
      SUM(CASE WHEN output_duration_ms > 0 AND output_tokens IS NOT NULL THEN output_tokens END) * 1000.0 /
        SUM(CASE WHEN output_duration_ms > 0 AND output_tokens IS NOT NULL THEN output_duration_ms END) AS outputTokensPerSecond,
      COUNT(CASE WHEN output_duration_ms > 0 AND output_tokens IS NOT NULL THEN 1 END) AS timedAttemptCount
    FROM timed_attempts
    GROUP BY provider_id, service_entry_id, consumer_id, operation, mapped_model
)
SELECT provider_id AS providerId,
       service_entry_id AS serviceEntryId, consumer_id AS consumerId, operation,
       model_id AS modelId, attempt_count AS attemptCount,
       successful_attempt_count AS successfulAttemptCount,
       reported_usage_attempt_count AS reportedUsageAttemptCount,
       input_tokens AS inputTokens, uncached_input_tokens AS uncachedInputTokens,
       cache_read_tokens AS cacheReadTokens, cache_write_tokens AS cacheWriteTokens,
       output_tokens AS outputTokens, reasoning_tokens AS reasoningTokens,
       total_tokens AS totalTokens,
       COALESCE((SELECT CAST(meta_value AS INTEGER) FROM provider_usage_meta WHERE meta_key = 'aggregate_revision'), 0) AS aggregateRevision,
       requestDurationMs, firstTokenLatencyMs, outputDurationMs, outputTokensPerSecond,
       COALESCE(timedAttemptCount, 0) AS timedAttemptCount, tariffUsageJson
 FROM range_usage
 LEFT JOIN daily_timing USING (provider_id, service_entry_id, consumer_id, operation, model_id)
 LEFT JOIN tariff_groups USING (provider_id, service_entry_id, consumer_id, operation, model_id)
 ORDER BY CASE WHEN ?6 = 'oldest' THEN latest_date END ASC,
          CASE WHEN ?6 = 'newest' THEN latest_date END DESC,
          provider_id, service_entry_id, consumer_id, operation, model_id
LIMIT 100 OFFSET (SELECT daily_offset FROM page_offsets);
]]) or vulcan.json.array()
    -- heatmap contains one exact aggregate per local calendar date for the selected range.
    -- heatmap 包含所选范围内的每个本地自然日精确聚合。
    local heatmap = (view == "all" or view == "overview") and query([[
, filtered AS (
    SELECT calendar_date, provider_id, model_id,
           COALESCE(total_tokens, 0) AS total_tokens,
           attempt_count, successful_attempt_count
    FROM filtered_daily
), daily AS (
    SELECT calendar_date, SUM(total_tokens) AS value,
           SUM(attempt_count) AS requests,
           SUM(successful_attempt_count) AS successes
    FROM filtered
    GROUP BY calendar_date
), ranked_models AS (
    SELECT calendar_date, provider_id, model_id,
           SUM(total_tokens) AS model_tokens,
           ROW_NUMBER() OVER (
               PARTITION BY calendar_date
               ORDER BY SUM(total_tokens) DESC, provider_id, model_id
           ) AS model_rank
    FROM filtered
    GROUP BY calendar_date, provider_id, model_id
)
SELECT d.calendar_date AS date,
       d.value AS value,
       d.requests AS requests,
       d.successes AS successes,
       r.provider_id AS topProviderName,
       r.model_id AS topModelName
FROM daily d
LEFT JOIN ranked_models r
    ON r.calendar_date = d.calendar_date AND r.model_rank = 1
ORDER BY d.calendar_date;
]]) or vulcan.json.array()
    -- series contains the daily projection; hourly_series owns the exact upper bound of the hourly projection.
    -- series 保存每日投影；hourly_series 持有每小时投影的精确结束边界。
    local series, hourly_series = vulcan.json.array(), nil
    if view == "all" or view == "overview" then
        -- hour_ms is the elapsed width of one bucket and defines the strict 24-hour cutoff.
        -- hour_ms 是每个分桶的实际时长，用于定义严格的 24 小时分界。
        local hour_ms = 3600000
        -- hourly uses the validated explicit bounds; legacy calendar ranges stay daily.
        -- hourly 使用已校验的显式时间边界；原有自然日范围仍按日统计。
        local hourly = input.startAtMs ~= nil and input.endAtMs - input.startAtMs < 24 * hour_ms
        -- bucket_source aligns hourly buckets to the start's local clock hour, then advances in elapsed hours.
        -- bucket_source 将每小时分桶对齐到起点所在的本地整点，之后按实际小时推进。
        local bucket_source = hourly and [[
, hour_anchor AS (
    SELECT (?10 / 60000 - CAST(strftime('%M', ?10 / 1000, 'unixepoch', 'localtime') AS INTEGER)) * 60000 AS first_hour
), bucket_usage AS (
    SELECT first_hour + ((terminal_at_ms - first_hour) / ]] .. hour_ms .. [[) * ]] .. hour_ms .. [[ AS bucket,
           provider_id, mapped_model AS model_id, known_total_tokens AS total_tokens
    FROM filtered_attempts CROSS JOIN hour_anchor
)
]] or [[
, bucket_usage AS (
    SELECT calendar_date AS bucket, provider_id, model_id, total_tokens FROM filtered_daily
)
]]
        -- bucket_column carries the matching typed key for consumers of each projection.
        -- bucket_column 为各投影的使用方提供对应的类型化键。
        local bucket_column = hourly and "hourStartAtMs" or "date"
        -- points shares model ranking across both grains so changing time buckets never changes the model totals.
        -- points 在两种粒度下共用模型排名，切换分桶不会改变模型总量。
        local points = query(bucket_source .. [[
, ranked_models AS (
    SELECT provider_id, model_id,
           SUM(COALESCE(total_tokens, 0)) AS metric_value
    FROM filtered_daily
    GROUP BY provider_id, model_id
    ORDER BY metric_value DESC, provider_id, model_id
    LIMIT 5
), classified AS (
    SELECT d.bucket,
           CASE WHEN r.provider_id IS NULL THEN 'other'
                ELSE r.provider_id || '/' || r.model_id END AS seriesKey,
           CASE WHEN r.provider_id IS NULL THEN 'Other'
                ELSE r.provider_id || ' / ' || r.model_id END AS label,
           COALESCE(d.total_tokens, 0) AS total_tokens
    FROM bucket_usage d
    LEFT JOIN ranked_models r
        ON r.provider_id = d.provider_id AND r.model_id = d.model_id
), projected AS (
    SELECT bucket, seriesKey, label, SUM(total_tokens) AS value
    FROM classified
    GROUP BY bucket, seriesKey, label
)
SELECT bucket AS ]] .. bucket_column .. [[, seriesKey, label, value
FROM projected
ORDER BY bucket, seriesKey;
]])
        if hourly then hourly_series = { endAtMs = input.endAtMs, points = points }
        else series = points end
    end
    local recent_attempts = include_recent and query([[
SELECT attempts.attempt_id AS attemptId, attempts.consumer_id AS consumerId,
       attempts.operation, attempts.provider_id AS providerId,
       attempts.service_entry_id AS serviceEntryId,
       attempts.mapped_model AS modelId, attempts.transport,
       attempts.http_status AS httpStatus,
       attempts.websocket_close_code AS websocketCloseCode,
       attempts.error_category AS errorCategory, attempts.error_code AS errorCode,
        attempts.status, attempts.usage_availability AS usageAvailability,
        attempts.input_tokens AS inputTokens,
        attempts.uncached_input_tokens AS uncachedInputTokens,
        attempts.cache_read_tokens AS cacheReadTokens,
        attempts.cache_write_tokens AS cacheWriteTokens,
        attempts.output_tokens AS outputTokens,
        attempts.reasoning_tokens AS reasoningTokens,
        attempts.audio_input_tokens AS audioInputTokens,
        attempts.audio_output_tokens AS audioOutputTokens,
        attempts.known_total_tokens AS totalTokens,
        attempts.provider_billing_details_json AS billingDetailsJson,
        attempts.terminal_at_ms AS terminalAtMs,
        attempts.request_duration_ms AS requestDurationMs,
        attempts.first_token_latency_ms AS firstTokenLatencyMs,
        attempts.output_duration_ms AS outputDurationMs,
        CASE WHEN attempts.output_duration_ms > 0 AND attempts.output_tokens IS NOT NULL
          THEN attempts.output_tokens * 1000.0 / attempts.output_duration_ms END AS outputTokensPerSecond,
        CASE WHEN attempts.output_duration_ms > 0 AND attempts.output_tokens IS NOT NULL THEN 1 ELSE 0 END AS timedAttemptCount
 FROM recent_model_attempts AS attempts
ORDER BY CASE WHEN ?6 = 'oldest' THEN attempts.terminal_at_ms END ASC,
         CASE WHEN ?6 = 'newest' THEN attempts.terminal_at_ms END DESC, attempts.attempt_id DESC
LIMIT 50 OFFSET (SELECT recent_offset FROM page_offsets);
    ]]) or vulcan.json.array()
    -- Aggregate choices before the exact model filter and pagination so switching can reach every model in scope.
    -- 在精确模型筛选及分页前汇总选项，以便切换到范围内的任意模型。
    local recent_models_sql = [[(SELECT json_group_array(json_object('providerId', provider_id, 'modelId', mapped_model))
        FROM (SELECT provider_id, mapped_model FROM recent_model_scope
              GROUP BY provider_id, mapped_model ORDER BY MAX(terminal_at_ms) DESC, provider_id, mapped_model))]]
    if page_only then
        -- Return only requested slices; never calculate overview costs, account snapshots or unrelated counts.
        -- 仅返回请求切片；不计算概览费用、账号快照或无关表格数量。
        local page = { view = view, aggregateRevision = initial_revision }
        if view ~= "recent-page" then
            local count_rows = query([[SELECT COUNT(*) AS count FROM range_usage;]])
            page.daily = daily
            page.dailyCount = count_rows[1].count
        end
        if include_recent then
            -- Read the filtered count and unfiltered choices together under the page revision guard.
            -- 在分页修订保护内一起读取筛选后的数量及完整模型选项。
            local recent_metadata = query([[SELECT (SELECT COUNT(*) FROM recent_model_attempts) AS count,
]] .. recent_models_sql .. [[ AS recentModelsJson;]])[1]
            page.recentAttempts = recent_attempts
            page.recentCount = recent_metadata.count
            page.recentModels = decode_json_text(recent_metadata.recentModelsJson, "recentModelsJson")
        end
        -- Capture the closing revision after both page rows and counts have been read.
        -- 在分页记录与数量均读取后捕获结束修订号。
        local page_revision_rows = sqlite_query([[
SELECT COALESCE(MAX(CAST(meta_value AS INTEGER)), 0) AS dashboardRevision,
       CAST(strftime('%s', 'now') AS INTEGER) * 1000 AS generatedAtMs
FROM provider_usage_meta WHERE meta_key = 'aggregate_revision';
]])
        if initial_revision ~= page_revision_rows[1].dashboardRevision then
            return nil, "page"
        end
        page.generatedAtMs = page_revision_rows[1].generatedAtMs
        return page
    end
    local accounts = (view == "all" or view == "maintenance") and sqlite_query([[
SELECT provider_id AS providerId, connection_id AS connectionId,
       snapshot_kind AS snapshotKind,
       endpoint_profile_revision AS endpointProfileRevision,
       payload_json AS payloadJson, observed_at_ms AS observedAtMs
FROM (
    SELECT provider_id, connection_id, snapshot_kind, endpoint_profile_revision,
           payload_json, observed_at_ms,
           ROW_NUMBER() OVER (
               PARTITION BY connection_id, snapshot_kind
               ORDER BY observed_at_ms DESC, snapshot_id DESC
           ) AS rowNumber
    FROM provider_account_usage_snapshots_v1
)
WHERE rowNumber = 1
ORDER BY providerId, connectionId, snapshotKind
LIMIT 500;
]]) or vulcan.json.array()
    -- providers lists every Provider in the scope without the Provider filter, so the selector keeps its options.
    -- providers 列出不含 Provider 筛选的作用域内全部 Provider，使选择器保留全部选项。
    local providers = (view == "all" or view == "providers") and query([[
SELECT provider_id AS providerId, COUNT(*) AS attempts,
       SUM(CASE WHEN status = 'succeeded' THEN 1 ELSE 0 END) AS successes,
       COALESCE(SUM(known_total_tokens), 0) AS totalTokens
FROM scoped_attempts
GROUP BY provider_id
ORDER BY attempts DESC, provider_id
LIMIT 200;
]]) or nil
    local meta_rows = query([[
SELECT CAST(strftime('%s', 'now') AS INTEGER) * 1000 AS generatedAtMs,
       (SELECT COUNT(*) FROM range_usage) AS dailyCount,
       (SELECT COUNT(*) FROM recent_model_attempts) AS recentCount,
       ]] .. (include_recent and recent_models_sql or "NULL") .. [[ AS recentModelsJson,
       (SELECT json_group_array(consumer_id) FROM
           (SELECT DISTINCT consumer_id FROM provider_usage_daily_v3 ORDER BY consumer_id)) AS consumerIdsJson,
       COALESCE(MAX(CASE WHEN meta_key = 'schema_revision'
                         THEN CAST(meta_value AS INTEGER) END), 0) AS schemaRevision,
       COALESCE(MAX(CASE WHEN meta_key = 'aggregate_revision'
                         THEN CAST(meta_value AS INTEGER) END), 0) AS aggregateRevision,
       COALESCE(MAX(CASE WHEN meta_key = 'health_status'
                         THEN meta_value END), 'unknown') AS healthStatus
FROM provider_usage_meta;
]])
    local meta = meta_rows[1]
    if type(meta) ~= "table" then
        error("Vulcan Usage Statistics could not read system statistics metadata")
    end
    if initial_revision ~= meta.aggregateRevision then
        return nil, "dashboard"
    end
    -- summary_rows aggregate the entire selected range, independent of detail pagination.
    -- summary_rows 聚合全部已选范围，不受明细分页影响。
    local summary_rows = query([[
SELECT COALESCE(SUM(attempt_count), 0) AS attempts,
       COALESCE(SUM(successful_attempt_count), 0) AS successes,
       COALESCE(SUM(reported_usage_attempt_count), 0) AS reported,
       COALESCE(SUM(total_tokens), 0) AS totalTokens,
       SUM(input_tokens) AS inputTokens, SUM(output_tokens) AS outputTokens,
       SUM(cache_read_tokens) AS cacheReadTokens, SUM(cache_write_tokens) AS cacheWriteTokens
FROM filtered_daily;
]])
    -- Use the same known quantities as the model table and track holes separately for coverage.
    -- 使用与模型表相同的已知用量，另行追踪缺失以标记覆盖范围。
    -- Group only rows sharing a price scope, model and usage availability for each dimension.
    -- 只合并计价范围、模型以及各维度的用量可用性一致的行。
    -- cost_page_size is the one page size shared by the SQL LIMIT and the paging loop.
    -- cost_page_size 是 SQL LIMIT 与分页循环共用的唯一页大小。
    local cost_page_size = 1000
    local cost_sql = tariff_sql .. [[
, cost_basis AS (
    SELECT CASE WHEN provider_id IN (SELECT key FROM json_each(?14, '$.providers')) THEN provider_id ELSE '' END AS pricing_provider,
      CASE WHEN provider_id IN (SELECT key FROM json_each(?14, '$.entryRefs')) THEN service_entry_id ELSE '' END AS pricing_entry,
      model_id, uncached_input_tokens, cache_read_tokens, cache_write_tokens, output_tokens,
      uncached_input_missing > 0 AS uncachedInputTokensMissing,
      cache_read_missing > 0 AS cacheReadTokensMissing,
      cache_write_missing > 0 AS cacheWriteTokensMissing,
      output_missing > 0 AS outputTokensMissing
    FROM range_usage
    LEFT JOIN tariff_groups USING (provider_id, service_entry_id, consumer_id, operation, model_id)
    WHERE ]] .. billing_model_sql("range_usage.model_id") .. [[ IN (SELECT value FROM json_each(?7))
      AND tariffUsageJson IS NULL
)
SELECT * FROM (
SELECT pricing_provider AS providerId, pricing_entry AS serviceEntryId, model_id AS modelId, COUNT(*) AS rowCount,
       SUM(uncached_input_tokens) AS uncachedInputTokens,
       SUM(cache_read_tokens) AS cacheReadTokens,
       SUM(cache_write_tokens) AS cacheWriteTokens,
       SUM(output_tokens) AS outputTokens,
       uncachedInputTokensMissing, cacheReadTokensMissing, cacheWriteTokensMissing, outputTokensMissing,
       NULL AS tariffUsageJson
FROM cost_basis
GROUP BY pricing_provider, pricing_entry, model_id, uncached_input_tokens IS NULL, cache_read_tokens IS NULL,
         cache_write_tokens IS NULL, output_tokens IS NULL,
         uncachedInputTokensMissing, cacheReadTokensMissing, cacheWriteTokensMissing, outputTokensMissing
UNION ALL
SELECT provider_id, service_entry_id, model_id, 1, NULL, NULL, NULL, NULL, 0, 0, 0, 0, tariffUsageJson FROM tariff_groups
)
ORDER BY providerId, serviceEntryId, modelId, uncachedInputTokens IS NULL, cacheReadTokens IS NULL,
         cacheWriteTokens IS NULL, outputTokens IS NULL,
         uncachedInputTokensMissing, cacheReadTokensMissing, cacheWriteTokensMissing, outputTokensMissing,
         tariffUsageJson
LIMIT ]] .. cost_page_size .. [[ OFFSET (SELECT cost_offset FROM page_offsets);
]]
    -- totals keeps independent exact sums and coverage counters for the two currencies.
    -- totals 为两种币种独立保留精确总额与覆盖计数。
    local totals = {
        USD = { digits = "0", scale = 0, priced = 0, incomplete = 0, partial = false },
        CNY = { digits = "0", scale = 0, priced = 0, incomplete = 0, partial = false },
    }
    while true do
      local cost_rows = query(cost_sql)
      for _, row in ipairs(cost_rows) do
        local estimates = attach_reference_estimate(row, config, price_cache, overrides)
        for currency, estimate in pairs(estimates) do
            local total = totals[currency]
            if estimate.amount == vulcan.json.null then
                total.incomplete = total.incomplete + row.rowCount
            else
                total.priced = total.priced + row.rowCount
                total.partial = total.partial or estimate.details.hasPartialUsage
                -- Align decimal places before adding this model group to its currency total.
                -- 先对齐小数位，再将模型分组小计计入对应币种总额。
                add_cost(total, estimate.amount)
            end
        end
      end
      if #cost_rows < cost_page_size then break end
      filter_params[8].value = filter_params[8].value + cost_page_size
    end
    -- Independent host queries do not share a read transaction; never publish mixed aggregate generations.
    -- 独立宿主查询不共享读取事务；绝不发布混合聚合代次。
    -- A changed revision makes the complete projection eligible for one retry by the action.
    -- 版本变化时，由 Action 对完整投影进行一次重读。
    local completed_revision_rows = sqlite_query([[
SELECT COALESCE(MAX(CAST(meta_value AS INTEGER)), 0) AS dashboardRevision
FROM provider_usage_meta WHERE meta_key = 'aggregate_revision';
]])
    if initial_revision ~= completed_revision_rows[1].dashboardRevision then
        return nil, "dashboard"
    end
    local costs = vulcan.json.array()
    for _, currency in ipairs({ "USD", "CNY" }) do
        local total = totals[currency]
        costs[#costs + 1] = {
            currency = currency,
            amount = total.priced > 0 and format_scaled_decimal(total.digits, total.scale) or vulcan.json.null,
            pricedRows = total.priced,
            incompleteRows = total.incomplete,
            unpricedRows = meta.dailyCount - total.priced - total.incomplete,
            hasPartialUsage = total.partial,
        }
    end
    summary_rows[1].costs = costs
    local dashboard = {
        generatedAtMs = meta.generatedAtMs,
        view = view,
        schemaRevision = meta.schemaRevision,
        aggregateRevision = meta.aggregateRevision,
        healthStatus = meta.healthStatus,
        dailyCount = meta.dailyCount,
        recentCount = meta.recentCount,
        summary = summary_rows[1],
        consumerIds = decode_json_text(meta.consumerIdsJson, "consumerIdsJson"),
        pricingCatalog = {
            catalogId = DEFAULT_PRICING_CATALOG.catalog_id,
            revision = DEFAULT_PRICING_CATALOG.revision,
            currency = DEFAULT_PRICING_CATALOG.currency,
            entryCount = DEFAULT_PRICING_CATALOG.entry_count,
            overrideCount = model_override_count(config),
            matchingStrategy = DEFAULT_PRICING_CATALOG.matching_strategy,
        },
        daily = daily,
        heatmap = heatmap,
        series = series,
        hourlySeries = hourly_series,
        recentAttempts = recent_attempts,
        accounts = accounts,
    }
    if providers then dashboard.providers = providers end
    if include_recent then dashboard.recentModels = decode_json_text(meta.recentModelsJson, "recentModelsJson") end
    return dashboard
end

-- Return the current plugin-owned model pricing overrides and default model list.
-- 返回当前插件自有模型价格覆盖与默认模型列表。
--
-- args contains the schema-validated empty action arguments.
-- args 包含通过 Schema 校验的空 Action 参数。
-- Returns a schema-validated settings projection.
-- 返回通过 Schema 校验的设置投影。
function M.settings_get(args)
    action_arguments(args)
    return success(settings_projection(read_config()))
end

-- Persist a complete plugin-owned model pricing override map.
-- 持久化完整的插件自有模型价格覆盖映射。
--
-- args.arguments is validated against the plugin configuration Schema by the host.
-- args.arguments 由宿主按插件配置 Schema 完成校验。
-- Returns the persisted settings projection.
-- 返回已经持久化的设置投影。
function M.settings_update(args)
    local input = action_arguments(args)
    -- Older callers omit the provider map; an explicit empty map still clears it.
    -- 旧调用方省略供应商映射；显式传入空映射仍可清空它。
    if input.providerOverrides == nil then input.providerOverrides = read_config().providerOverrides end
    -- Validate windows and context tier ordering before any configuration write.
    -- 写入任何配置之前校验时段和上下文档位顺序。
    for _, prices in pairs(input.modelOverrides) do tariff_rule(prices) end
    for _, model_overrides in pairs(input.providerOverrides or {}) do
        for _, prices in pairs(model_overrides) do tariff_rule(prices) end
    end
    local updated = vulcan.host.call("vulcan.plugin.config.update", { value = input })
    return success(settings_projection(updated))
end

-- Load one revision-bound preview for clearing all historical statistics.
-- 加载一个绑定修订的全部历史统计清理预览。
--
-- Returns the current attempt count, known Token total, and aggregate revision.
-- 返回当前请求数、已知 Token 总量和聚合修订号。
local function load_clear_preview()
    local rows = sqlite_query([[
SELECT COUNT(*) AS attemptCount,
       COALESCE(SUM(]] .. KNOWN_TOTAL_TOKENS_SQL .. [[), 0) AS totalTokens,
       COALESCE((SELECT CAST(meta_value AS INTEGER)
                 FROM provider_usage_meta
                 WHERE meta_key = 'aggregate_revision'), 0) AS aggregateRevision
FROM provider_usage_attempts_v3;
]])
    local preview = rows[1]
    if type(preview) ~= "table" then
        error("Vulcan Usage Statistics could not preview statistics cleanup")
    end
    return preview
end

-- Load the authoritative Provider usage dashboard from system VLDB.
-- 从系统 VLDB 加载权威 Provider 用量仪表盘。
--
-- args contains the schema-validated range, consumer, model, order, view and page offsets.
-- args 包含通过 Schema 校验的范围、消费者、模型、顺序、视图与分页偏移。
-- Returns the dashboard in the managed plugin ABI envelope.
-- 在受管插件 ABI 信封中返回仪表盘。
function M.dashboard_get(args)
    -- input retains the exact action arguments across both reads.
    -- input 在两次读取中保留完全相同的 Action 参数。
    local input = action_arguments(args)
    if input.startAtMs ~= nil and input.endAtMs <= input.startAtMs then
        error("The end time must be later than the start time")
    end
    -- Capture the same prices and rate for pagination, retries and displayed details.
    -- 分页、重试和展示明细共用同一份单价与汇率。
    local config, price_cache = read_config(), {}
    local overrides = index_pricing_overrides(config)
    local rules = pricing_rules(overrides)
    -- dashboard is populated only by a complete read; conflict names a discarded projection.
    -- dashboard 仅由完整读取填充；conflict 标识被丢弃的投影类别。
    local dashboard, conflict = load_dashboard(input, config, price_cache, overrides, rules)
    if dashboard == nil then
        dashboard, conflict = load_dashboard(input, config, price_cache, overrides, rules)
    end
    if dashboard == nil then
        error("Vulcan Usage Statistics: statistics changed during loading; refresh to read a consistent " .. conflict)
    end

    -- Enrich the accepted rows after the revision check to keep the read window short.
    -- 在版本检查通过后补全已接受的记录，以缩短读取窗口。
    -- Page projections omit row sets outside their declared view.
    -- 分页投影省略其声明视图范围之外的记录集。
    for _, row in ipairs(dashboard.daily or EMPTY_ARRAY) do
        attach_reference_estimate(row, config, price_cache, overrides)
    end
    for _, attempt in ipairs(dashboard.recentAttempts or EMPTY_ARRAY) do
        if attempt.billingDetailsJson == nil or attempt.billingDetailsJson == vulcan.json.null then
            attempt.billingDetails = vulcan.json.array()
        else
            attempt.billingDetails = decode_json_text(
                attempt.billingDetailsJson,
                "provider_billing_details_json"
            )
        end
        attempt.billingDetailsJson = nil
        attempt.isOffPeak = is_off_peak(attempt.providerId, attempt.serviceEntryId, attempt.modelId, attempt.terminalAtMs, rules)
        attach_reference_estimate(attempt, config, price_cache, overrides)
    end
    for _, account in ipairs(dashboard.accounts or EMPTY_ARRAY) do
        account.payload = decode_json_text(account.payloadJson, "payload_json")
        account.payloadJson = nil
    end
    return success(dashboard)
end

-- Query one complete, searchable pricing-directory page across catalog, overrides and retained usage.
-- 在目录、覆盖与保留用量之间查询一页完整且可搜索的定价目录。
-- args contains search, filter and offset; returns at most twenty-five priced model rows.
-- args 包含 search、filter 与 offset；返回最多二十五个已投影模型行。
function M.pricing_get(args)
    local input = action_arguments(args)
    local config = read_config()
    local overrides = index_pricing_overrides(config)
    local provider = overrides.providers[input.providerId]
    -- Catalog and override keys describe pricing eligibility after model grouping.
    -- 目录与覆盖键描述模型分组后的定价资格。
    local catalog_ids, override_ids, declared_ids = vulcan.json.array(), vulcan.json.array(), vulcan.json.array()
    local scoped_ids = vulcan.json.array()
    local legacy_ids = vulcan.json.array()
    -- Scoped catalog IDs are selectable even when the shared version floor hides the model.
    -- 即使共享版本下限隐藏该模型，供应商刊例仍可在专属范围选用。
    local scoped_catalog_ids, catalog_provider_ids = vulcan.json.array(), vulcan.json.array()
    local provider_catalog = DEFAULT_PRICING_CATALOG.provider_models[input.providerId]
    if provider_catalog ~= nil then
        for model_id in pairs(provider_catalog) do scoped_catalog_ids[#scoped_catalog_ids + 1] = model_id end
    end
    for provider_id in pairs(DEFAULT_PRICING_CATALOG.provider_models) do
        catalog_provider_ids[#catalog_provider_ids + 1] = provider_id
    end
    for model_id in pairs(DEFAULT_PRICING_CATALOG.models) do catalog_ids[#catalog_ids + 1] = model_id end
    for model_id in pairs(DEFAULT_PRICING_CATALOG.native_unit_references) do catalog_ids[#catalog_ids + 1] = model_id end
    for model_id in pairs(overrides.shared.groups) do override_ids[#override_ids + 1] = model_id end
    for model_id in pairs(config.modelOverrides) do legacy_ids[#legacy_ids + 1] = model_id end
    if provider ~= nil then
        for model_id in pairs(provider.groups) do scoped_ids[#scoped_ids + 1] = model_id end
        for model_id in pairs(provider.prices) do legacy_ids[#legacy_ids + 1] = model_id end
    end
    for _, model_id in ipairs(DECLARED_MODEL_IDS) do declared_ids[#declared_ids + 1] = model_id end
    for model_id in pairs(DECLARED_MODEL_ALIASES) do
        if not PRICING_HIDDEN_MODEL_IDS[model_id] then declared_ids[#declared_ids + 1] = model_id end
    end
    -- Keep substring and suffix searches, folding case when excluding model IDs from the directory.
    -- 保留子串与后缀搜索，并在从费用目录排除型号标识时统一大小写。
    local search = input.search or ""
    local rows = sqlite_query([[
WITH ]] .. billing_lookup_sql("?7") .. [[,
hidden_ids AS MATERIALIZED (SELECT lower(key) AS model_id FROM json_each(?10)),
scoped_catalog AS (SELECT value AS model_id FROM json_each(?14)),
catalog AS (SELECT value AS model_id FROM json_each(?1) UNION SELECT model_id FROM scoped_catalog),
shared_overrides AS (SELECT value AS model_id FROM json_each(?2)),
scoped_overrides AS (SELECT value AS model_id FROM json_each(?13)),
overrides AS (SELECT model_id FROM shared_overrides UNION SELECT model_id FROM scoped_overrides),
used AS (SELECT model_id, SUM(attempt_count) AS attempts FROM provider_usage_daily_v3
    WHERE ?12 = '' OR provider_id = ?12 GROUP BY model_id),
declared AS (SELECT value AS model_id FROM json_each(?6)),
identities AS (SELECT model_id FROM catalog UNION SELECT model_id FROM overrides UNION SELECT model_id FROM used
    UNION SELECT model_id FROM declared UNION SELECT value FROM json_each(?8)),
models AS (
    SELECT i.model_id AS raw_model, COALESCE((SELECT model_id FROM scoped_catalog
        WHERE model_id = lower(]] .. model_id_suffix_sql("i.model_id") .. [[)), ]] .. billing_model_sql("i.model_id") .. [[) AS model_id,
        COALESCE(u.attempts, 0) AS attempts
    FROM identities i LEFT JOIN used u ON i.model_id = u.model_id
), numeric_ids AS (
    SELECT model_id, 'gpt' AS family, substr(lower(model_id), 5) AS version
    FROM models WHERE lower(model_id) GLOB 'gpt-[0-9]*'
    UNION ALL
    SELECT model_id, 'minimax' AS family, substr(lower(model_id), 10) AS version
    FROM models WHERE lower(model_id) GLOB 'minimax-m[0-9]*'
), version_parts AS (
    SELECT model_id, family, CAST(version AS INTEGER) AS major, ltrim(version, '0123456789') AS suffix
    FROM numeric_ids
), numeric_versions AS (
    SELECT model_id, family, major,
        CASE WHEN suffix GLOB '.[0-9]*' OR (family = 'gpt' AND (suffix GLOB '-[0-9]' OR suffix GLOB '-[0-9]-*'
            OR suffix GLOB '-[0-9][0-9]' OR suffix GLOB '-[0-9][0-9]-*'))
            THEN substr(suffix, 2) ELSE '0' || suffix END AS minor_and_variant
    FROM version_parts
), excluded_models AS (
    SELECT model_id FROM hidden_ids
    UNION SELECT lower(model_id) FROM numeric_versions
    WHERE (family = 'minimax' AND (major, CAST(minor_and_variant AS INTEGER)) <
        (json_extract(?11, '$.minimax.major'), json_extract(?11, '$.minimax.minor')))
      OR (family = 'gpt' AND ((major, CAST(minor_and_variant AS INTEGER)) <
        (json_extract(?11, '$.minimum.major'), json_extract(?11, '$.minimum.minor'))
      OR ((major, CAST(minor_and_variant AS INTEGER)) >=
        (json_extract(?11, '$.named.major'), json_extract(?11, '$.named.minor'))
        AND ltrim(minor_and_variant, '0123456789') NOT IN (SELECT value FROM json_each(?11, '$.named.variants'))
        AND NOT (major = json_extract(?11, '$.named.astra_major') AND ltrim(minor_and_variant, '0123456789') = '-astra'))))
), filtered AS (
    SELECT m.model_id, SUM(m.attempts) AS attempts
    FROM models m
    WHERE (lower(m.model_id) NOT IN (SELECT model_id FROM excluded_models)
           OR m.model_id IN (SELECT model_id FROM scoped_overrides UNION SELECT model_id FROM scoped_catalog))
      AND (?4 IN ('all', 'used')
        OR (?4 = 'override' AND (
             (?12 = '' AND m.model_id IN (SELECT model_id FROM shared_overrides))
             OR (?12 <> '' AND m.model_id IN (SELECT model_id FROM scoped_overrides))))
        OR (?4 = 'unpriced' AND m.model_id NOT IN (SELECT model_id FROM catalog UNION SELECT model_id FROM overrides)))
    GROUP BY m.model_id
    HAVING (?4 <> 'used' OR SUM(m.attempts) > 0)
       AND (?3 = '' OR instr(lower(m.model_id), lower(?3)) > 0 OR MAX(instr(lower(m.raw_model), lower(?3))) > 0
            OR lower(m.model_id) = lower(?9))
), page AS (SELECT * FROM filtered ORDER BY model_id LIMIT 25 OFFSET ?5)
SELECT json_object('totalCount', (SELECT COUNT(*) FROM filtered),
    'providerIds', json((SELECT json_group_array(provider_id) FROM (
        SELECT provider_id FROM provider_usage_daily_v3
        UNION SELECT value AS provider_id FROM json_each(?15) ORDER BY provider_id))),
    'models', json((SELECT json_group_array(json_object('modelId', page.model_id, 'attempts', page.attempts,
        'aliases', json((SELECT json_group_array(model_suffix) FROM
            (SELECT model_suffix FROM billing_aliases
                WHERE model_id = page.model_id AND model_suffix <> lower(model_id)
                AND model_suffix NOT IN (SELECT model_id FROM scoped_catalog)
                AND model_suffix NOT IN (SELECT model_id FROM hidden_ids) ORDER BY model_suffix LIMIT 25)))))
        FROM page))) AS resultJson;
]], {
        { kind = "string", value = vulcan.json.encode(catalog_ids) },
        { kind = "string", value = vulcan.json.encode(override_ids) },
        { kind = "string", value = search },
        { kind = "string", value = input.filter or "all" },
        { kind = "int64", value = input.offset or 0 },
        { kind = "string", value = vulcan.json.encode(declared_ids) },
        { kind = "string", value = billing_lookup_json() },
        { kind = "string", value = vulcan.json.encode(legacy_ids) },
        { kind = "string", value = billing_model_id(search) },
        { kind = "string", value = vulcan.json.encode(PRICING_HIDDEN_MODEL_IDS) },
        { kind = "string", value = vulcan.json.encode({
            minimum = MINIMUM_GPT_PRICING_VERSION, named = NAMED_GPT_PRICING, minimax = MINIMUM_MINIMAX_PRICING_VERSION,
        }) },
        { kind = "string", value = input.providerId or "" },
        { kind = "string", value = vulcan.json.encode(scoped_ids) },
        { kind = "string", value = vulcan.json.encode(scoped_catalog_ids) },
        { kind = "string", value = vulcan.json.encode(catalog_provider_ids) },
    })
    local result = decode_json_text(rows[1].resultJson, "pricing directory")
    result.currency = DEFAULT_PRICING_CATALOG.currency
    for _, row in ipairs(result.models) do
        -- Show official media rates without treating media units as tokens in estimates.
        -- 展示官方媒体报价，估算时不将媒体单位当作 Token。
        local native_reference = DEFAULT_PRICING_CATALOG.native_unit_references[row.modelId]
        if native_reference ~= nil then
            local rates = vulcan.json.array()
            for _, rate in ipairs(native_reference.rates) do rates[#rates + 1] = rate end
            row.nativeUnitRates = rates
        end
        local group = (provider and provider.groups[row.modelId]) or overrides.shared.groups[billing_model_id(row.modelId)]
        if group ~= nil and group.conflict then
            row.effectivePrices = vulcan.json.object()
            row.source = "conflict"
        else
            local explicit, effective, source = model_prices(row.modelId, config, overrides, input.providerId)
            row.effectivePrices = effective
            row.source = source
            if explicit ~= nil and explicit.offPeak ~= nil then
                row.offPeakPrices = effective_prices(explicit.offPeak.prices, config)
            end
        end
    end
    return success(result)
end

-- Preview clearing all historical Provider statistics without mutating data.
-- 预览清理全部 Provider 历史统计，且不修改数据。
--
-- args contains the schema-validated empty action arguments.
-- args 包含通过 Schema 校验的空 Action 参数。
-- Returns a revision-bound cleanup preview.
-- 返回一个绑定修订的清理预览。
function M.statistics_clear_preview(args)
    action_arguments(args)
    return success(load_clear_preview())
end

-- Clear all historical Provider statistics at the exact preview revision.
-- 在精确预览修订上清理全部 Provider 历史统计。
--
-- args contains expectedAggregateRevision from the latest preview.
-- args 包含最近一次预览的 expectedAggregateRevision。
-- Returns the cleared counts and the cleanup revision.
-- 返回清理数量和清理修订号。
function M.statistics_clear_apply(args)
    local input = action_arguments(args)
    local expected_revision = input.expectedAggregateRevision
    if type(expected_revision) ~= "number"
        or expected_revision % 1 ~= 0
        or expected_revision < 0 then
        error("expectedAggregateRevision must be a non-negative integer")
    end
    local preview = load_clear_preview()
    if preview.aggregateRevision ~= expected_revision then
        error("System statistics changed after cleanup preview; preview again")
    end
    local revision_literal = tostring(expected_revision)
    local result = sqlite_execute([[
BEGIN IMMEDIATE;
DELETE FROM provider_rate_limit_snapshots_v1
WHERE EXISTS (
    SELECT 1 FROM provider_usage_meta
    WHERE meta_key = 'aggregate_revision'
      AND CAST(meta_value AS INTEGER) = ]] .. revision_literal .. [[
);
DELETE FROM provider_usage_attempts_v3
WHERE EXISTS (
    SELECT 1 FROM provider_usage_meta
    WHERE meta_key = 'aggregate_revision'
      AND CAST(meta_value AS INTEGER) = ]] .. revision_literal .. [[
);
DELETE FROM provider_usage_daily_v3
WHERE EXISTS (
    SELECT 1 FROM provider_usage_meta
    WHERE meta_key = 'aggregate_revision'
      AND CAST(meta_value AS INTEGER) = ]] .. revision_literal .. [[
);
DELETE FROM provider_account_usage_snapshots_v1
WHERE EXISTS (
    SELECT 1 FROM provider_usage_meta
    WHERE meta_key = 'aggregate_revision'
      AND CAST(meta_value AS INTEGER) = ]] .. revision_literal .. [[
);
UPDATE provider_usage_meta
SET meta_value = CAST(meta_value AS INTEGER) + 1,
    updated_at_ms = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE meta_key = 'aggregate_revision'
  AND CAST(meta_value AS INTEGER) = ]] .. revision_literal .. [[;
COMMIT;
]])
    if type(result) ~= "table" or type(result.rows_changed) ~= "number" then
        error("Vulcan Usage Statistics received an invalid VLDB cleanup result")
    end
    if result.rows_changed < 1 then
        error("System statistics changed during cleanup; preview again")
    end
    return success({
        clearedAttemptCount = preview.attemptCount,
        clearedTokenCount = preview.totalTokens,
        aggregateRevision = expected_revision + 1,
    })
end

-- Reject generic model-visible dispatch because this plugin exposes UI actions only.
-- 拒绝通用模型可见分发，因为当前插件仅暴露界面 Action。
--
-- args contains an unsupported generic invocation.
-- args 包含一条不受支持的通用调用。
-- This function always raises an explicit capability error.
-- 当前函数始终抛出明确的能力错误。
function M.dispatch(args)
    error("Vulcan Usage Statistics does not expose provider-visible plugin tools")
end

-- Close one action runtime lease without retaining plugin-owned statistics state.
-- 关闭一个 Action 运行时租约，且不保留插件自有统计状态。
--
-- args contains the host-owned lease shutdown context.
-- args 包含宿主持有的租约关闭上下文。
-- Returns one successful close acknowledgement.
-- 返回一条成功关闭确认。
function M.shutdown(args)
    return success({ closed = true })
end

return M
